INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (1,'en','{\"image\":\"/bg-hero.webp\",\"eyebrow\":\"Dhaka Bypass Expressway\",\"headline\":\"Eighteen kilometres open, and tolling\",\"standfirst\":\"The first section of the bypass carries traffic between Vogra and Purbachal today. The rest of the 48-kilometre corridor is still under construction.\",\"primaryLabel\":\"Toll rates\",\"primaryHref\":\"travel/toll\",\"secondaryLabel\":\"What is open\",\"secondaryHref\":\"travel/status\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (1,'bn','{\"image\":\"/bg-hero.webp\",\"eyebrow\":\"Dhaka Bypass Expressway\",\"headline\":\"আঠারো কিলোমিটার খোলা, টোল আদায় চালু\",\"standfirst\":\"বাইপাসের প্রথম অংশ আজ Vogra ও Purbachal-এর মধ্যে যান চলাচল বহন করছে। ৪৮ কিলোমিটার করিডোরের বাকি অংশ এখনও নির্মাণাধীন।\",\"primaryLabel\":\"টোল হার\",\"primaryHref\":\"travel/toll\",\"secondaryLabel\":\"কী খোলা আছে\",\"secondaryHref\":\"travel/status\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (1,'zh','{\"image\":\"/bg-hero.webp\",\"eyebrow\":\"Dhaka Bypass Expressway\",\"headline\":\"18公里已通车并开始收费\",\"standfirst\":\"快速路首段目前在 Vogra 至 Purbachal 之间承担通行。全长48公里走廊的其余路段仍在建设中。\",\"primaryLabel\":\"通行费标准\",\"primaryHref\":\"travel/toll\",\"secondaryLabel\":\"通车路段\",\"secondaryHref\":\"travel/status\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (2,'en','{\"heading\":\"What it costs\",\"intro\":\"Rates in force on the open section. Motorcycles and three-wheelers may not use the expressway.\",\"classes\":[\"car\",\"microbus\",\"large_bus\",\"heavy_truck\"],\"linkLabel\":\"All nine vehicle classes\",\"linkHref\":\"travel/toll\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (2,'bn','{\"heading\":\"খরচ কত\",\"intro\":\"খোলা অংশে বর্তমানে কার্যকর টোল হার। মোটরসাইকেল ও তিন চাকার যানবাহন এক্সপ্রেসওয়ে ব্যবহার করতে পারবে না।\",\"classes\":[\"car\",\"microbus\",\"large_bus\",\"heavy_truck\"],\"linkLabel\":\"নয়টি শ্রেণির সবগুলি\",\"linkHref\":\"travel/toll\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (2,'zh','{\"heading\":\"通行费用\",\"intro\":\"已通车路段现行的通行费标准。摩托车和三轮车不得驶入本快速路。\",\"classes\":[\"car\",\"microbus\",\"large_bus\",\"heavy_truck\"],\"linkLabel\":\"全部九类车型\",\"linkHref\":\"travel/toll\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (3,'en','{\"image\":\"/bypass-ex.webp\",\"side\":\"right\",\"heading\":\"A road around the city, not through it\",\"body\":\"<p>The Dhaka Bypass runs 48 kilometres down the eastern edge of the capital, from Gazipur in the north to Narayanganj in the south. It exists so that freight moving between the northern industrial belt and the southern ports does not have to cross Dhaka to get there.</p><p>It is access-controlled: traffic joins and leaves only at built interchanges, and every crossing is grade-separated. That is what separates it from the national highways it connects to, and it is why a journey that today crosses the city is meant to bypass it entirely once the full corridor opens.</p>\",\"caption\":\"The completed carriageway on the open section.\",\"linkLabel\":\"Where to join and leave\",\"linkHref\":\"travel/route\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (3,'bn','{\"image\":\"/bypass-ex.webp\",\"side\":\"right\",\"heading\":\"শহরের ভেতর দিয়ে নয়, শহরকে ঘিরে\",\"body\":\"<p>Dhaka Bypass রাজধানীর পূর্ব প্রান্ত ধরে উত্তরে গাজীপুর থেকে দক্ষিণে নারায়ণগঞ্জ পর্যন্ত ৪৮ কিলোমিটার বিস্তৃত। উত্তরের শিল্পাঞ্চল ও দক্ষিণের বন্দরগুলির মধ্যে চলাচলকারী পণ্যবাহী যানবাহনকে যাতে ঢাকা পার হয়ে যেতে না হয়, সে জন্যই এই সড়ক।</p><p>এটি নিয়ন্ত্রিত-প্রবেশ সড়ক: যানবাহন কেবল নির্মিত ইন্টারচেঞ্জ দিয়েই ওঠে ও নামে, আর প্রতিটি ক্রসিং আলাদা স্তরে করা। এখানেই এটি সংযুক্ত জাতীয় মহাসড়কগুলির থেকে আলাদা, এবং এ কারণেই শহরের ভেতর দিয়ে যে যাত্রায় দুই ঘণ্টা লাগে, সম্পূর্ণ করিডোর খুলে গেলে তা তার সামান্য সময়েই শেষ হওয়ার কথা।</p>\",\"caption\":\"খোলা অংশের নির্মিত ক্যারেজওয়ে।\",\"linkLabel\":\"কোথায় উঠবেন ও নামবেন\",\"linkHref\":\"travel/route\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (3,'zh','{\"image\":\"/bypass-ex.webp\",\"side\":\"right\",\"heading\":\"绕开城市，而不是穿城而过\",\"body\":\"<p>Dhaka Bypass 沿首都东缘延伸48公里，北起加济普尔，南至纳拉扬甘杰。修建它，是为了让往返于北部工业带与南部港口之间的货运车辆不必穿越达卡。</p><p>本路实行出入控制：车辆只能在已建成的互通立交上下，所有交叉均为立体交叉。这正是它与所衔接的各条国道的区别所在，也是全线通车之后，原本需要穿城的行程得以绕城而过的原因。</p>\",\"caption\":\"已通车路段建成的行车道。\",\"linkLabel\":\"上下路的位置\",\"linkHref\":\"travel/route\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (4,'en','{\"heading\":\"What it connects\",\"intro\":\"Four national highways meet the corridor along its length.\",\"items\":[{\"meta\":\"North end\",\"title\":\"N3\",\"body\":\"The Dhaka–Mymensingh highway at Joydebpur, toward the north.\"},{\"meta\":\"North\",\"title\":\"N4\",\"body\":\"The Tangail and Jamuna bridge corridor, toward the north-west.\"},{\"meta\":\"Mid-corridor\",\"title\":\"N2\",\"body\":\"The Dhaka–Sylhet highway, toward the north-east.\"},{\"meta\":\"South end\",\"title\":\"N1\",\"body\":\"The Dhaka–Chattogram highway at Madanpur, toward the southern ports.\"}]}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (4,'bn','{\"heading\":\"কীসের সঙ্গে সংযোগ\",\"intro\":\"করিডোর বরাবর চারটি জাতীয় মহাসড়ক এসে মিলেছে।\",\"items\":[{\"meta\":\"উত্তর প্রান্ত\",\"title\":\"N3\",\"body\":\"Joydebpur-এ ঢাকা–ময়মনসিংহ মহাসড়ক, উত্তর দিকে।\"},{\"meta\":\"উত্তর\",\"title\":\"N4\",\"body\":\"টাঙ্গাইল ও যমুনা সেতু করিডোর, উত্তর-পশ্চিম দিকে।\"},{\"meta\":\"করিডোরের মাঝামাঝি\",\"title\":\"N2\",\"body\":\"ঢাকা–সিলেট মহাসড়ক, উত্তর-পূর্ব দিকে।\"},{\"meta\":\"দক্ষিণ প্রান্ত\",\"title\":\"N1\",\"body\":\"Madanpur-এ ঢাকা–চট্টগ্রাম মহাসড়ক, দক্ষিণের বন্দরের দিকে।\"}]}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (4,'zh','{\"heading\":\"衔接哪些道路\",\"intro\":\"沿线共有四条国道与本走廊相交。\",\"items\":[{\"meta\":\"北端\",\"title\":\"N3\",\"body\":\"在 Joydebpur 衔接达卡–迈门辛国道，通往北方。\"},{\"meta\":\"北段\",\"title\":\"N4\",\"body\":\"丹盖尔与贾木纳大桥走廊，通往西北方向。\"},{\"meta\":\"走廊中段\",\"title\":\"N2\",\"body\":\"达卡–锡尔赫特国道，通往东北方向。\"},{\"meta\":\"南端\",\"title\":\"N1\",\"body\":\"在 Madanpur 衔接达卡–吉大港国道，通往南部港口。\"}]}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (5,'en','{\"stats\":[{\"label\":\"Corridor length\",\"value\":\"48\",\"unit\":\"km\"},{\"label\":\"Open to traffic\",\"value\":\"18\",\"unit\":\"km\"},{\"label\":\"Vehicle classes tolled\",\"value\":\"9\",\"unit\":\"\"},{\"label\":\"National highways joined\",\"value\":\"4\",\"unit\":\"\"}]}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (5,'bn','{\"stats\":[{\"label\":\"করিডোরের দৈর্ঘ্য\",\"value\":\"৪৮\",\"unit\":\"কিমি\"},{\"label\":\"যান চলাচলের জন্য খোলা\",\"value\":\"১৮\",\"unit\":\"কিমি\"},{\"label\":\"টোলভুক্ত যানবাহন শ্রেণি\",\"value\":\"৯\",\"unit\":\"\"},{\"label\":\"সংযুক্ত জাতীয় মহাসড়ক\",\"value\":\"৪\",\"unit\":\"\"}]}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (5,'zh','{\"stats\":[{\"label\":\"走廊全长\",\"value\":\"48\",\"unit\":\"公里\"},{\"label\":\"已通车里程\",\"value\":\"18\",\"unit\":\"公里\"},{\"label\":\"收费车型数\",\"value\":\"9\",\"unit\":\"\"},{\"label\":\"衔接国道数\",\"value\":\"4\",\"unit\":\"\"}]}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (6,'en','{\"image\":\"/photo/16.webp\",\"side\":\"left\",\"heading\":\"What the open section changes now\",\"body\":\"<p>Traffic that used to queue through Gazipur can now run the tolled section instead. For a freight operator that is measured in fuel burned while stationary and in drivers’ hours, not in kilometres saved.</p><p>The corridor is built and operated under a public–private partnership covering design, construction, finance, operation and maintenance. Tolls are what pays for it.</p><p class=\\\"db-provisional-inline\\\">Figures published for this project during construction — total investment, jobs created, bridges and underpasses built, the length of the concession — have not been reconfirmed since the road opened. They are not republished here until DBEDC has verified them.</p>\",\"caption\":\"The finished wearing course on the open section.\",\"linkLabel\":\"The corridor today\",\"linkHref\":\"travel/status\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (6,'bn','{\"image\":\"/photo/16.webp\",\"side\":\"left\",\"heading\":\"খোলা অংশ এখন কী বদলাচ্ছে\",\"body\":\"<p>আগে যে যানবাহনকে গাজীপুরের ভেতর দিয়ে যানজটে দাঁড়িয়ে থাকতে হতো, তা এখন টোল দিয়ে খোলা অংশ ব্যবহার করতে পারে। পণ্যপরিবহন সংস্থার কাছে এর হিসাব কিলোমিটার সাশ্রয়ে নয় — দাঁড়িয়ে থাকা অবস্থায় পুড়ে যাওয়া জ্বালানি আর চালকের কর্মঘণ্টায়।</p><p>করিডোরটি নির্মিত ও পরিচালিত হচ্ছে একটি সরকারি–বেসরকারি অংশীদারত্বের অধীনে, যার আওতায় রয়েছে নকশা, নির্মাণ, অর্থায়ন, পরিচালনা ও রক্ষণাবেক্ষণ। এর খরচ ওঠে টোল থেকেই।</p><p class=\\\"db-provisional-inline\\\">নির্মাণকালে এই প্রকল্প নিয়ে যেসব হিসাব প্রকাশিত হয়েছিল — মোট বিনিয়োগ, সৃষ্ট কর্মসংস্থান, নির্মিত সেতু ও আন্ডারপাসের সংখ্যা, কনসেশনের মেয়াদ — সড়ক খুলে দেওয়ার পর সেগুলি আর নিশ্চিত করা হয়নি। DBEDC যাচাই না করা পর্যন্ত সেগুলি এখানে পুনঃপ্রকাশ করা হচ্ছে না।</p>\",\"caption\":\"খোলা অংশের চূড়ান্ত পৃষ্ঠস্তর।\",\"linkLabel\":\"আজকের করিডোর\",\"linkHref\":\"travel/status\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (6,'zh','{\"image\":\"/photo/16.webp\",\"side\":\"left\",\"heading\":\"已通车路段带来的改变\",\"body\":\"<p>过去必须在加济普尔排队通行的车辆，如今可以改走收费路段。对货运企业来说，这笔账不是省下多少公里，而是怠速中烧掉的燃油和司机的工时。</p><p>本走廊在政府与社会资本合作（PPP）模式下建设和运营，涵盖设计、施工、融资、运营与养护。通行费是其资金来源。</p><p class=\\\"db-provisional-inline\\\">施工期间就本项目公布过的数据——总投资、创造的就业岗位、建成的桥梁与地下通道数量、特许经营期限——在道路通车后均未重新确认。在 DBEDC 核实之前，这些数据不会在此重新发布。</p>\",\"caption\":\"已通车路段建成的沥青面层。\",\"linkLabel\":\"今日通行状况\",\"linkHref\":\"travel/status\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (7,'en','{\"heading\":\"The corridor\",\"intro\":\"The alignment during construction and since opening.\",\"items\":[{\"image\":\"/photo/22.webp\",\"caption\":\"The viaduct crossing the river.\"},{\"image\":\"/photo/20.webp\",\"caption\":\"Traffic on the open section.\"},{\"image\":\"/photo/21.webp\",\"caption\":\"Bridge construction over open water.\"},{\"image\":\"/photo/18.webp\",\"caption\":\"Surfacing at dusk.\"},{\"image\":\"/photo/17.webp\",\"caption\":\"Compacting the wearing course.\"},{\"image\":\"/photo/23.webp\",\"caption\":\"Looking south along the deck.\"}],\"linkLabel\":\"\",\"linkHref\":\"\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (7,'bn','{\"heading\":\"করিডোর\",\"intro\":\"নির্মাণকালে এবং খুলে দেওয়ার পর অ্যালাইনমেন্ট।\",\"items\":[{\"image\":\"/photo/22.webp\",\"caption\":\"নদী পার হওয়া ভায়াডাক্ট।\"},{\"image\":\"/photo/20.webp\",\"caption\":\"খোলা অংশে যান চলাচল।\"},{\"image\":\"/photo/21.webp\",\"caption\":\"উন্মুক্ত জলের উপর সেতু নির্মাণ।\"},{\"image\":\"/photo/18.webp\",\"caption\":\"সন্ধ্যায় পৃষ্ঠস্তর বসানো।\"},{\"image\":\"/photo/17.webp\",\"caption\":\"পৃষ্ঠস্তর কম্প্যাক্ট করা হচ্ছে।\"},{\"image\":\"/photo/23.webp\",\"caption\":\"ডেক বরাবর দক্ষিণ দিকে।\"}],\"linkLabel\":\"\",\"linkHref\":\"\"}','published',NULL,'2026-09-04 15:54:53');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`, `updated_by`, `updated_at`) VALUES (7,'zh','{\"heading\":\"走廊沿线\",\"intro\":\"施工期间与通车之后的线路。\",\"items\":[{\"image\":\"/photo/22.webp\",\"caption\":\"跨河高架桥。\"},{\"image\":\"/photo/20.webp\",\"caption\":\"已通车路段的车流。\"},{\"image\":\"/photo/21.webp\",\"caption\":\"开阔水面上的桥梁施工。\"},{\"image\":\"/photo/18.webp\",\"caption\":\"傍晚摊铺沥青面层。\"},{\"image\":\"/photo/17.webp\",\"caption\":\"碾压面层。\"},{\"image\":\"/photo/23.webp\",\"caption\":\"沿桥面向南望。\"}],\"linkLabel\":\"\",\"linkHref\":\"\"}','published',NULL,'2026-09-04 15:54:53');
