INSERT IGNORE INTO `media` (`id`, `path`, `width`, `height`, `bytes`, `mime`, `focal_x`, `focal_y`, `alt`, `created_at`, `origin`, `credit`, `original_path`) VALUES (1,'/bg-hero.webp',686,386,143706,'image/webp',0.500,0.500,'{\"en\":\"The expressway seen from the air, curving between wetland and villages with traffic on the open carriageway\",\"bn\":\"আকাশ থেকে তোলা এক্সপ্রেসওয়ে, জলাভূমি ও গ্রামের মাঝ দিয়ে বাঁক নিয়ে গেছে, খোলা ক্যারেজওয়েতে যান চলাচল করছে\",\"zh\":\"从空中俯瞰快速路，在湿地与村庄之间蜿蜒，已通车的行车道上有车辆通行\"}','2026-09-04 15:54:53','legacy','DBEDC',NULL);
INSERT IGNORE INTO `media` (`id`, `path`, `width`, `height`, `bytes`, `mime`, `focal_x`, `focal_y`, `alt`, `created_at`, `origin`, `credit`, `original_path`) VALUES (2,'/bypass-ex.webp',696,408,58246,'image/webp',0.500,0.500,'{\"en\":\"A gantry over the carriageway reading “Welcome to Dhaka Bypass Expressway”, with the toll plaza and trucks beyond\",\"bn\":\"ক্যারেজওয়ের উপরে একটি গ্যান্ট্রিতে লেখা “Welcome to Dhaka Bypass Expressway”, তার ওপাশে টোল প্লাজা ও ট্রাক\",\"zh\":\"行车道上方的龙门架写着“Welcome to Dhaka Bypass Expressway”，后方是收费广场和货车\"}','2026-09-04 15:54:53','legacy','DBEDC',NULL);
